// HOST-SIDE shim for `cloudflare:workers`, `cloudflare:email` and `rwsdk/worker`, bundled into the
// desktop binary in place of the real modules. Actions and db modules that do
// `import { env } from "cloudflare:workers"` get the host's env (sqlite D1, KV,
// in-process DOs); `requestInfo` is the one local identity. Actions are only
// reachable on the host's token-gated page, so this is always the host: a
// remote guest reaches the world socket alone and carries its identity there.
declare global { var __RB_ENV: Record<string, unknown> | undefined; var __RB_IDENTITY: Record<string, string> | undefined; }

export const env: Record<string, any> = new Proxy({}, {
  get: (_t, k) => globalThis.__RB_ENV?.[k as string],
  has: (_t, k) => !!globalThis.__RB_ENV && k in globalThis.__RB_ENV,
  ownKeys: () => Object.keys(globalThis.__RB_ENV ?? {}),
  getOwnPropertyDescriptor: (_t, k) => ({ enumerable: true, configurable: true, value: globalThis.__RB_ENV?.[k as string] }),
});

export class DurableObject<E = unknown> {
  constructor(public ctx: any, public env: E) {}
}
export class WorkerEntrypoint<E = unknown> { constructor(public ctx: any, public env: E) {} }
export class WorkflowEntrypoint<E = unknown> { constructor(public ctx: any, public env: E) {} }
/** cloudflare:workflows' error that fails a step.do without its retries. */
export class NonRetryableError extends Error {
  constructor(message: string) { super(message); this.name = "NonRetryableError"; }
}
/** cloudflare:email's message: a holder for the envelope and the raw MIME text, for env.EMAIL.send(). */
export class EmailMessage {
  constructor(readonly from: string, readonly to: string, readonly raw: string | ReadableStream | ArrayBuffer | Uint8Array) {}
}
/** Base class for objects passed by reference over RPC; capnweb (in rwsdk) extends it at load. */
export class RpcTarget {}

/** rwsdk/worker's requestInfo, local edition. */
export const requestInfo = {
  get ctx() { const id = globalThis.__RB_IDENTITY ?? {}; return { user: { id: id["X-User-Id"] ?? "local", name: id["X-User-Name"] ?? "local" }, session: null }; },
  get headers() { return new Headers(globalThis.__RB_IDENTITY ?? {}); },
  request: null as Request | null,
  response: { headers: new Headers(), status: 200 },
};
export const getRequestInfo = () => requestInfo;
/** rwsdk's defineScript (seed scripts and the like): a function that runs fn with the env. */
export const defineScript = (fn: (a: { env: Record<string, any> }) => unknown) => () => fn({ env });
export const waitUntil =(p: Promise<unknown>) => { void p.catch((e) => console.error("[waitUntil]", e)); };
export const defineApp = (routes: unknown) => ({ fetch: async () => new Response("rwsdk app is not run on the desktop; use spa mode", { status: 501 }), routes });
export const route = (..._a: unknown[]) => null;
export const render = (..._a: unknown[]) => null;
export const prefix = (..._a: unknown[]) => null;

// rwsdk 1.x server functions: interruptors run first and a Response from one ends
// the call; the registered wrap runs around the handler. Same shape as rwsdk's own.
type Interruptor = (c: { request: Request | null; ctx: unknown; args: unknown[] }) => unknown;
type Wrap = (fn: Function, args: unknown[], type: "action" | "query") => Promise<unknown>;
let wrap: Wrap | undefined;
export const registerServerFunctionWrap = (w: Wrap) => { wrap = w; };
function serverFunction(type: "action" | "query", fnsOrFn: Function | Function[], options?: { method?: "GET" | "POST" }) {
  const fns = Array.isArray(fnsOrFn) ? fnsOrFn : [fnsOrFn];
  const main = fns.at(-1)!;
  const wrapped = Object.assign(async (...args: unknown[]) => {
    for (const fn of fns.slice(0, -1)) {
      const r = await (fn as Interruptor)({ request: requestInfo.request, ctx: requestInfo.ctx, args });
      if (r instanceof Response) return r;
    }
    return wrap ? wrap(main, args, type) : main(...args);
  }, { method: options?.method ?? (type === "query" ? "GET" : "POST") });
  return wrapped;
}
export const serverQuery = (fnsOrFn: Function | Function[], options?: { method?: "GET" | "POST" }) => serverFunction("query", fnsOrFn, options);
export const serverAction = (fnsOrFn: Function | Function[], options?: { method?: "GET" | "POST" }) => serverFunction("action", fnsOrFn, options);
